// HU-3: arma el cuerpo de embedContent para cada boletin.
// Modelo y dimensiones FIJOS en el nodo (si cambian, hay que reindexar todo: ver migracion 009).
const MODELO = 'gemini-embedding-001';
const DIMS = 768;
const MAX_CHARS = 6000; // limite del modelo: 2048 tokens (~1500-2000 tokens en espanol)
const t0 = Date.now();
return $input.all().map((it, idx) => {
  const texto = String(it.json.resumen || '');
  return {
    json: {
      id_boletin: it.json.id_boletin,
      anio: it.json.anio,
      semana: it.json.semana_epidemiologica,
      truncado: texto.length > MAX_CHARS,
      _t0: t0,
      body: {
        model: 'models/' + MODELO,
        content: { parts: [{ text: texto.slice(0, MAX_CHARS) }] },
        taskType: 'RETRIEVAL_DOCUMENT',   // los boletines son los "documentos"; la pregunta usara RETRIEVAL_QUERY
        outputDimensionality: DIMS,
      },
    },
    pairedItem: idx,
  };
});

// HU-3: valida la dimension y normaliza (L2). Un vector malo NO llega al UPDATE (la fila sigue pendiente).
// gemini-embedding-001 con outputDimensionality distinto de 3072 requiere normalizar a mano.
const MODELO = 'gemini-embedding-001';
const DIMS = 768;
const pedidos = $('Preparar solicitud de embedding').all();
return $input.all().map((it, idx) => {
  const ped = (pedidos[idx] && pedidos[idx].json) || {};
  const vec = it.json && it.json.embedding && it.json.embedding.values;
  let ok = Array.isArray(vec) && vec.length === DIMS && vec.every(Number.isFinite);
  let norma = 0;
  if (ok) { norma = Math.sqrt(vec.reduce((s, x) => s + x * x, 0)); ok = norma > 0; }
  const motivo = ok ? '' : (it.json && it.json.error
      ? 'HTTP/red: ' + String((it.json.error.message || it.json.error)).slice(0, 120)
      : (Array.isArray(vec) ? 'dimension ' + vec.length + ' != ' + DIMS : 'respuesta sin embedding'));
  return {
    json: {
      id_boletin: ped.id_boletin, anio: ped.anio, semana: ped.semana, truncado: !!ped.truncado, _t0: ped._t0,
      ok,
      embedding: ok ? JSON.stringify(vec.map(x => x / norma)) : null,   // $2
      modelo: ok ? MODELO : null,                                        // $3
      motivo,
    },
    pairedItem: idx,
  };
});

const { construirTrazaPhoenix } = require('@healthradar/core');
// HU-3 (Phoenix): un span por corrida del indexador (cuantos boletines se indexaron y cuantos fallaron).
const evaluados = $('Validar y normalizar vector').all().map(i => i.json);
const guardados = $input.all().filter(i => i.json && i.json.id_boletin !== undefined && i.json.id_boletin !== null).length;
const fallidos = evaluados.filter(e => !e.ok);
const inicio = evaluados.length ? evaluados[0]._t0 : undefined;
const resumen = `Indexados ${guardados} de ${evaluados.length} boletines`
  + (fallidos.length ? `; ${fallidos.length} pendientes (${[...new Set(fallidos.map(f => f.motivo))].join(' | ').slice(0, 300)})` : '');
const traza = construirTrazaPhoenix({
  nombre: 'boletin.embedding',
  entrada: `Indexar embeddings (${evaluados.length} boletines: ${evaluados.map(e => e.anio + '-S' + e.semana).join(', ').slice(0, 300)})`,
  salida: resumen,
  modelo: 'gemini-embedding-001',
  inicioMs: inicio, finMs: Date.now(),
  sessionId: 'healthradar-embeddings',
  exito: fallidos.length === 0,
  error: fallidos.length ? resumen : '',
  metadatos: { flujo: 'Indexar embeddings', proveedor: 'google', tarea: 'embedding', evaluados: evaluados.length, guardados, fallidos: fallidos.length, truncados: evaluados.filter(e => e.truncado).length },
});
return [{ json: { traza } }];
